package tw.com.tft.documentscanner.export;import android.content.*;import android.media.MediaScannerConnection;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import java.io.*;import java.text.*;import java.util.*;import tw.com.tft.documentscanner.*;import tw.com.tft.documentscanner.imaging.*;import tw.com.tft.documentscanner.model.ScanItem;import tw.com.tft.documentscanner.util.DeviceProfile;public final class ExportManager{public static File renderToCache(Context c,ScanItem i,int n,String folder)throws Exception{File d=new File(c.getCacheDir(),folder);if(!d.exists()&&!d.mkdirs())throw new IllegalStateException("dir");File o=new File(d,name(n));int m=DeviceProfile.finalMaxSide(c);return ScannerApp.isOpenCvReady()?ImageProcessor.processFull(i.sourcePath,i.corners,i.filter,o,m):FallbackProcessor.processFull(i.sourcePath,i.corners,i.filter,o,m);}public static Uri saveToPictures(Context c,ScanItem i,int n)throws Exception{File r=renderToCache(c,i,n,"scan_outputs");if(Build.VERSION.SDK_INT>=29){ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,r.getName());v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");v.put(MediaStore.Images.Media.RELATIVE_PATH,Environment.DIRECTORY_PICTURES+"/文件掃描與裁切");v.put(MediaStore.Images.Media.IS_PENDING,1);Uri u=c.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IllegalStateException("media");try(OutputStream o=c.getContentResolver().openOutputStream(u);FileInputStream in=new FileInputStream(r)){byte[]b=new byte[65536];int x;while((x=in.read(b))>0)o.write(b,0,x);}v.clear();v.put(MediaStore.Images.Media.IS_PENDING,0);c.getContentResolver().update(u,v,null,null);return u;}File d=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),"文件掃描與裁切");d.mkdirs();File t=new File(d,r.getName());try(FileInputStream in=new FileInputStream(r);FileOutputStream o=new FileOutputStream(t)){byte[]b=new byte[65536];int x;while((x=in.read(b))>0)o.write(b,0,x);}MediaScannerConnection.scanFile(c,new String[]{t.getAbsolutePath()},new String[]{"image/jpeg"},null);return Uri.fromFile(t);}public static List<Uri> saveAll(Context c,List<ScanItem>i)throws Exception{List<Uri>o=new ArrayList<>();for(int x=0;x<i.size();x++)o.add(saveToPictures(c,i.get(x),x+1));return o;}private static String name(int n){return String.format(Locale.TAIWAN,"文件_%s_%02d.jpg",new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.TAIWAN).format(new Date()),n);}}